-- ============================================================================
-- 联机工具箱2.0 贴图查看器数据表（条目4.6）
-- 数据来源：移植自本作者旧作 TextureViewer（Mods\Texture查看器）TV/TV_Data.sql
--       （原文件由 build_texture_list.py 生成：游戏本体+全部 DLC .blp 包全部 UI 贴图，
--       共 5017 行；表名 Texture_Collection -> MPT_TextureCollection，MPT_ 前缀规约）
-- 读取：本表仅前端 StagingRoom.lua 条目4.6 分区顶层经 DB.ConfigurationQuery 一次性
--       预加载纯数据（同条目4.5 图标查看器先例）。
-- ============================================================================
CREATE TABLE IF NOT EXISTS 'MPT_TextureCollection' (
    'TextureName' TEXT NOT NULL,
    'SourceBlp'   TEXT NOT NULL,
    PRIMARY KEY ('TextureName')
);

